namespace sarif.export.ep;





using ghidra.program.model.address;
using ghidra.util.exception;
using ghidra.util.task;
using sarif.export;
using sarif.export;
using sarif.managers;

public class SarifEntryPointWriter : AbstractExtWriter {
	
	private List<Address> entryPoints;

	public SarifEntryPointWriter(List<Address> request, Writer baseWriter)
    : base(baseWriter)
    {
		this.entryPoints = request;
	}

	/* @Override */
	protected void genRoot(TaskMonitor monitor)
    {
		genCode(monitor);
		root.add("entryPoints", objects);
	}

	private void genCode(TaskMonitor monitor)
    {
		monitor.initialize(entryPoints.size());
		foreach (Address addr in entryPoints) {
			monitor.checkCancelled();
			ExtEntryPoint isf = new ExtEntryPoint(addr);
			SarifObject sarif = new SarifObject(ExtEntryPointSarifMgr.SUBKEY, ExtEntryPointSarifMgr.KEY, getTree(isf), addr, addr);
			objects.add(getTree(sarif));
			monitor.increment();
		}
	}

}
